
.world-header-epic {
  background: linear-gradient(180deg, rgba(0, 0, 0, 0.6) 0%, transparent 100%);
  border-bottom: 2px solid var(--c-deep-gold);
  padding: 20px 30px;
}

.top-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
}

.meta-item,
.clock-display,
.location-display {
  display: flex;
  flex-direction: column;
}

.label {
  font-family: var(--font-title);
  font-size: 10px;
  color: var(--c-parchment-dark);
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 4px;
}

.value {
  font-family: var(--font-title);
  font-weight: 900;
  font-size: 18px;
  color: var(--c-parchment-light);
}

.time-container {
  display: flex;
  flex-direction: column;
  .date {
    font-size: 11px;
    color: var(--c-parchment-dark);
    line-height: 1;
  }
  .time {
    font-family: var(--font-title);
    font-size: 22px;
    font-weight: 900;
    color: var(--c-gold-bright);
    text-shadow: 0 0 10px rgba(241, 196, 15, 0.3);
  }
}

.gold-glow {
  color: var(--c-gold-bright);
  text-shadow: 0 0 12px rgba(241, 196, 15, 0.4);
}

.event-marquee {
  margin-top: 20px;
  display: flex;
  gap: 15px;
  overflow-x: auto;
  padding: 5px 2px 10px;

  &::-webkit-scrollbar {
    height: 4px;
  }
  &::-webkit-scrollbar-thumb {
    background: var(--c-deep-gold);
    border-radius: 2px;
  }
}

.event-card {
  flex: 0 0 auto;
  min-width: 160px;
  background: rgba(255, 255, 255, 0.03);
  border-left: 2px solid var(--c-gold-bright);
  padding: 10px 15px;
  border-radius: 0 4px 4px 0;
  box-shadow: 4px 4px 10px rgba(0, 0, 0, 0.2);
  opacity: 0;
}

@keyframes slide-in-right {
  from {
    opacity: 0;
    transform: translateX(30px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.ani-slide-in {
  animation: slide-in-right 0.6s cubic-bezier(0.23, 1, 0.32, 1) forwards;
}

.event-name {
  display: block;
  font-family: var(--font-title);
  font-size: 12px;
  font-weight: bold;
  color: var(--c-gold-bright);
  letter-spacing: 1px;
}

.event-desc {
  display: block;
  font-size: 11px;
  color: var(--c-parchment-dark);
  margin-top: 4px;
  line-height: 1.4;
}
