
.panel-header-simple {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
  border-bottom: 1px solid var(--c-deep-gold);
  padding-bottom: 8px;
}

.capacity-bar {
  font-size: 11px;
  color: var(--c-parchment-dark);
  .bind-count b {
    color: var(--c-gold-bright);
    font-size: 14px;
    font-family: var(--font-title);
  }
}

.contract-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 15px;
}

.contract-card-modern {
  background: rgba(10, 10, 10, 0.4);
  border: 1px solid rgba(139, 108, 66, 0.3);
  border-radius: 4px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition: all 0.3s cubic-bezier(0.19, 1, 0.22, 1);
  opacity: 0;
  animation: slide-in-bottom 0.5s ease-out forwards;

  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: var(--c-silver-ash);
    opacity: 0.5;
  }

  &:hover {
    transform: translateY(-5px);
    border-color: var(--c-gold-bright);
    background: rgba(20, 20, 20, 0.6);
  }

  &.active {
    border-color: var(--c-gold-bright) !important;
    &::before {
      background: var(--c-gold-bright);
      box-shadow: 0 0 10px var(--c-gold-bright);
    }
  }

  /* 类型配色 */
  &.t-melee::before {
    background: var(--c-ruby-red);
  }
  &.t-range::before {
    background: #3498db;
  }
  &.t-supp::before {
    background: var(--c-magic-teal);
  }
  &.t-spec::before {
    background: var(--c-magic-purple);
  }

  .card-inner {
    padding: 12px;
    height: 100%;
    display: flex;
    flex-direction: column;
  }
}

.contract-header {
  margin-bottom: 10px;
}

.soul-type {
  font-size: 9px;
  text-transform: uppercase;
  color: var(--c-parchment-dark);
  display: block;
  letter-spacing: 1px;
  margin-bottom: 2px;
}

.soul-name {
  font-family: var(--font-title);
  font-size: 15px;
  color: var(--c-parchment-light);
  margin: 0;
}

.ability-wrap {
  flex: 1;
  min-height: 48px;
}

.soul-ability {
  font-size: 11px;
  color: var(--c-parchment-dark);
  line-height: 1.4;
  margin: 0;
}

.card-footer {
  margin-top: 10px;
  display: flex;
  align-items: center;
}

.status-indicator {
  font-size: 10px;
  color: var(--c-parchment-dark);
  display: flex;
  align-items: center;
  gap: 5px;

  .dot {
    width: 4px;
    height: 4px;
    background: currentColor;
    border-radius: 50%;
  }
}

.active .status-indicator {
  color: var(--c-gold-bright);
  .dot {
    box-shadow: 0 0 5px var(--c-gold-bright);
    animation: pulse-glow-dot 2s infinite;
  }
}

.empty-slot-card {
  border: 1px dashed rgba(139, 108, 66, 0.2);
  border-radius: 4px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 20px;
  color: rgba(139, 108, 66, 0.3);

  .slot-plus {
    font-size: 24px;
    line-height: 1;
    margin-bottom: 5px;
  }
  .slot-text {
    font-size: 10px;
    text-transform: uppercase;
    letter-spacing: 1px;
  }
}

/* 觉醒遮罩层 */
.summon-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.85);
  backdrop-filter: blur(8px);
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
}

.summon-modal-modern {
  width: 90%;
  max-width: 600px;
  background: linear-gradient(145deg, #1a1a1a, #0d0d0d);
  border: 2px solid var(--c-gold-muted);
  box-shadow:
    0 0 50px rgba(0, 0, 0, 0.8),
    0 0 30px rgba(139, 108, 66, 0.2);
  padding: 40px;
  text-align: center;
  position: relative;
  border-radius: 8px;
}

.awakening-title {
  font-size: 28px;
  color: var(--c-gold-bright);
  margin-bottom: 15px;
  text-shadow: 0 0 15px rgba(241, 196, 15, 0.4);
}

.awakening-desc {
  font-style: italic;
  color: var(--c-parchment-dark);
  margin-bottom: 30px;
  font-size: 13px;
}

.candidate-row {
  display: flex;
  gap: 20px;
  justify-content: center;
}

.candidate-card-epic {
  flex: 1;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--c-gold-muted);
  padding: 20px;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  position: relative;
  opacity: 0;
  animation: fade-in-up 0.6s forwards;

  &:hover {
    transform: scale(1.05) translateY(-10px);
    border-color: var(--c-gold-bright);
    background: rgba(255, 255, 255, 0.08);
    box-shadow:
      0 10px 30px rgba(0, 0, 0, 0.5),
      0 0 20px rgba(241, 196, 15, 0.2);

    .bind-action {
      background: var(--c-gold-bright);
      color: #000;
    }
  }
}

.type-tag {
  font-size: 9px;
  color: var(--c-silver-ash);
  text-transform: uppercase;
  margin-bottom: 8px;
}

.c-name {
  font-family: var(--font-title);
  font-size: 18px;
  color: var(--c-parchment-light);
  margin-bottom: 12px;
}

.c-ability {
  font-size: 11px;
  color: var(--c-parchment-dark);
  line-height: 1.5;
  margin-bottom: 20px;
  min-height: 45px;
}

.bind-action {
  font-family: var(--font-title);
  font-size: 10px;
  padding: 8px;
  border: 1px solid var(--c-gold-muted);
  color: var(--c-gold-bright);
  transition: all 0.3s;
}

/* 动画定义 */
@keyframes slide-in-bottom {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes pulse-glow-dot {
  0%,
  100% {
    opacity: 0.5;
  }
  50% {
    opacity: 1;
  }
}

.summon-modal-fancy-enter-active,
.summon-modal-fancy-leave-active {
  transition: all 0.5s ease;
  .summon-modal-modern {
    transition: all 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  }
}

.summon-modal-fancy-enter-from,
.summon-modal-fancy-leave-to {
  opacity: 0;
  .summon-modal-modern {
    transform: scale(0.8) translateY(20px);
  }
}
